def suffix(line,length):
 out=[line[-1]];remaining=length
 for a,b in reversed(list(zip(line,line[1:]))):
  d=math.dist(a,b)
  if d>=remaining:
   out.append([b[k]+(a[k]-b[k])*remaining/d for k in (0,1)]);break
  out.append(a);remaining-=d
 return out[::-1]

